package com.ryu.forkliftdiagnostic.ui;
import android.app.Activity; import android.content.Intent; import android.graphics.Color; import android.graphics.Typeface; import android.view.Gravity; import android.widget.*; import com.ryu.forkliftdiagnostic.MainActivity;
public final class Ui { private Ui(){} public static LinearLayout page(Activity a,String title){ScrollView s=new ScrollView(a);LinearLayout b=new LinearLayout(a);b.setOrientation(LinearLayout.VERTICAL);b.setPadding(24,20,24,48);b.setBackgroundColor(Color.rgb(246,248,250));s.addView(b);a.setContentView(s);LinearLayout bar=new LinearLayout(a);bar.setGravity(Gravity.CENTER_VERTICAL);Button h=button(a,"⌂ 홈");h.setContentDescription("home");h.setOnClickListener(v->{Intent i=new Intent(a,MainActivity.class);i.addFlags(Intent.FLAG_ACTIVITY_CLEAR_TOP);a.startActivity(i);});bar.addView(h);TextView t=text(a,title,22,true);bar.addView(t,new LinearLayout.LayoutParams(0,-2,1));b.addView(bar);return b;} public static TextView text(Activity a,String s,int z,boolean bold){TextView v=new TextView(a);v.setText(s);v.setTextSize(z);v.setTextColor(Color.rgb(24,30,36));v.setPadding(18,12,18,12);if(bold)v.setTypeface(Typeface.DEFAULT,Typeface.BOLD);return v;} public static Button button(Activity a,String s){Button b=new Button(a);b.setText(s);b.setAllCaps(false);b.setGravity(Gravity.START|Gravity.CENTER_VERTICAL);b.setTextSize(16);return b;} }
